/*
 * The maquette format: a lo-fi mock-up a PM agent writes as `<name>.maquette.json` (screens built from a small catalogue of blocks, goto
 * links between them, an optional workflow and its cases). Plain data drawn by `MaquetteViewer`: nothing in it is built or runs.
 * The format is documented in registry/README.md ("Maquette viewer"). Model output is untrusted: `parseMaquette` reads it defensively,
 * keeps what it understands, bounds every list and string, and never throws. The workflow is a diagram (`parseDiagram` of the
 * diagram-viewer item reads it), written inline or linked as a `*.diagram.json` path.
 */
import { parseDiagram } from '../diagram-viewer/diagram';
import type { Diagram, DiagramEdge, DiagramNode } from '../diagram-viewer/diagram';

/** The format version this viewer writes and reads. A file without `version` is read as version 1. */
export const MAQUETTE_FORMAT_VERSION = 1;

/** A block as written in format v1. `type` picks the drawing; the other fields are read by the types that use them. */
export interface MaquetteBlockV1 {
  readonly type: string;
  /** A stable name for the block, used when someone comments on it; its position (`2`, `2.0` for a child) otherwise. */
  readonly id?: string;
  /** The block's words (`text` and `title` are accepted as aliases). */
  readonly label?: string;
  readonly text?: string;
  readonly title?: string;
  /** The screen id a click on this block opens (buttons, links, list items, placeholders). */
  readonly goto?: string;
  /** A primary button. */
  readonly primary?: boolean;
  /** Nested blocks of `card`, `row`, `stack` (`blocks` is accepted as an alias). */
  readonly children?: readonly MaquetteBlockV1[];
  readonly blocks?: readonly MaquetteBlockV1[];
  /** `list` rows, or `select` options. */
  readonly items?: readonly string[];
  readonly options?: readonly string[];
  /** `table` header and rows. */
  readonly columns?: readonly string[];
  readonly rows?: readonly (readonly string[])[];
  /** `chat` messages; `from: "user"` (or `person`, `me`, `moi`) is the person's side. */
  readonly messages?: readonly { readonly from?: string; readonly text?: string }[];
  /** `document` lines. */
  readonly lines?: readonly string[];
  /** `input`, `select` and `chat` hint and value. */
  readonly placeholder?: string;
  readonly value?: string;
  /** A placeholder's note under its name. */
  readonly note?: string;
}

/** A maquette file as written in format v1. */
export interface MaquetteFileV1 {
  /** Absent means 1. */
  readonly version?: 1;
  readonly title?: string;
  /** The screen id play mode opens first; the first screen otherwise. */
  readonly start?: string;
  /** The frame screens are drawn in: a light phone or desktop frame. Absent: the panel's width. */
  readonly device?: 'phone' | 'desktop';
  /** Screens by id, in the order the stepper walks them. `note` says why the screen exists and what the person does there. */
  readonly screens: Readonly<Record<string, { readonly title?: string; readonly note?: string; readonly blocks: readonly MaquetteBlockV1[] }>>;
  /** The app's navigation bar, shown above every screen. */
  readonly nav?: readonly { readonly label: string; readonly goto: string }[];
  /**
   * The workflow understood: states and the transitions between them (`on` is accepted as an alias of `label`). It is a diagram (format v1
   * of `*.diagram.json`: `nodes`/`edges` are the same as `states`/`transitions`, plus optional `groups`, `path` and `note`), or the path of a
   * `*.diagram.json` file, relative to the maquette's folder.
   */
  readonly workflow?: string | {
    readonly states?: readonly ({ readonly id: string; readonly label?: string; readonly group?: string } | string)[];
    readonly transitions?: readonly { readonly from: string; readonly to: string; readonly label?: string; readonly on?: string; readonly by?: string }[];
    readonly nodes?: readonly ({ readonly id: string; readonly label?: string; readonly group?: string } | string)[];
    readonly edges?: readonly { readonly from: string; readonly to: string; readonly label?: string; readonly on?: string; readonly by?: string }[];
    readonly groups?: readonly ({ readonly id: string; readonly label?: string } | string)[];
    readonly path?: readonly string[];
    readonly note?: string;
  };
  /**
   * Cases. `steps` makes a guided tour: its screens in order, each with a caption ("Camille receives the invoice and approves it").
   * `path` (workflow state ids) highlights the case in the workflow diagram. A case may carry both.
   */
  readonly cases?: readonly { readonly name: string; readonly steps?: readonly { readonly screen: string; readonly caption?: string }[]; readonly path?: readonly string[] }[];
}

/** A block as the viewer draws it: every field read, bounded and defaulted. */
export interface MaquetteBlock {
  readonly type: string;
  /** The block's `id`, or its position among the screen's blocks (`2`, `2.0` for the first child of the third block). */
  readonly id: string;
  readonly label: string;
  readonly goto: string | undefined;
  readonly primary: boolean;
  readonly children: readonly MaquetteBlock[];
  readonly items: readonly string[];
  readonly columns: readonly string[];
  readonly rows: readonly (readonly string[])[];
  readonly messages: readonly { readonly mine: boolean; readonly text: string }[];
  readonly lines: readonly string[];
  readonly placeholder: string;
  readonly value: string;
  readonly note: string;
}
export interface MaquetteScreen { readonly id: string; readonly title: string; readonly note: string; readonly blocks: readonly MaquetteBlock[] }
export type MaquetteState = DiagramNode;
export type MaquetteTransition = DiagramEdge;
export interface MaquetteWorkflow { readonly states: readonly MaquetteState[]; readonly transitions: readonly MaquetteTransition[] }
export interface MaquetteCase { readonly name: string; readonly steps: readonly { readonly screen: string; readonly caption: string }[]; readonly path: readonly string[] }
/** A maquette ready to draw. */
export interface Maquette {
  readonly title: string;
  readonly start: string;
  readonly device: 'phone' | 'desktop' | undefined;
  readonly screens: readonly MaquetteScreen[];
  readonly nav: readonly { readonly label: string; readonly goto: string }[];
  readonly workflow: MaquetteWorkflow | null;
  /** The inline workflow as a diagram (with its groups, path and note), for `DiagramView`. */
  readonly diagram: Diagram | null;
  /** The `*.diagram.json` path the workflow links to, as written (relative to the maquette's folder). */
  readonly diagramLink: string | undefined;
  readonly cases: readonly MaquetteCase[];
}

/**
 * The outcome of reading a file. `version` is the file's declared version (1 when absent); a version above `MAQUETTE_FORMAT_VERSION`
 * is read as v1, best effort. `invalid` is not JSON (`json`) or has no screen to show (`shape`).
 */
export type MaquetteParse =
  | { readonly kind: 'ok'; readonly maquette: Maquette; readonly version: number }
  | { readonly kind: 'invalid'; readonly reason: 'json' | 'shape'; readonly version: number | undefined };

const MINE = new Set(['user', 'person', 'me', 'moi']);
const str = (value: unknown, max = 400): string => typeof value === 'string' ? value.slice(0, max) : typeof value === 'number' && Number.isFinite(value) ? String(value) : '';
const arr = (value: unknown, max = 60): readonly unknown[] => Array.isArray(value) ? value.slice(0, max) : [];
const obj = (value: unknown): Record<string, unknown> => value !== null && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
const strings = (value: unknown, max: number, length = 120): string[] => arr(value, max).map(item => str(item, length));

function block(value: unknown, depth: number, at: string): MaquetteBlock | null {
  const raw = obj(value);
  const type = str(raw['type'], 40).trim().toLowerCase();
  if (!type || depth > 6) return null;
  const goto = str(raw['goto'], 60);
  return {
    type, id: str(raw['id'], 60).trim() || at, label: str(raw['label'] ?? raw['text'] ?? raw['title']), goto: goto || undefined, primary: raw['primary'] === true,
    children: arr(raw['children'] ?? raw['blocks'], 40).map((child, index) => block(child, depth + 1, `${at}.${index}`)).filter((child): child is MaquetteBlock => child !== null),
    items: strings(raw['items'] ?? raw['options'], 12),
    columns: strings(raw['columns'], 8, 40),
    rows: arr(raw['rows'], 12).map(row => strings(row, 8, 80)),
    messages: arr(raw['messages'], 10).map(item => { const message = obj(item); return { mine: MINE.has(str(message['from'], 20).toLowerCase()), text: str(message['text'], 600) }; }).filter(message => message.text),
    lines: strings(raw['lines'], 16, 300),
    placeholder: str(raw['placeholder'], 120), value: str(raw['value'], 120), note: str(raw['note'], 200),
  };
}

/** Reads a maquette (its JSON text or an already parsed value). Never throws. */
export function parseMaquette(input: unknown): MaquetteParse {
  let raw: unknown = input;
  if (typeof raw === 'string') {
    try { raw = JSON.parse(raw); } catch { return { kind: 'invalid', reason: 'json', version: undefined }; }
  }
  const spec = obj(raw);
  const declared = spec['version'];
  const version = declared === undefined ? 1 : typeof declared === 'number' && Number.isSafeInteger(declared) && declared >= 1 ? declared : undefined;
  if (version === undefined) return { kind: 'invalid', reason: 'shape', version: undefined };
  const screens = Object.entries(obj(spec['screens'])).slice(0, 30).map(([id, value]): MaquetteScreen => {
    const screen = obj(value);
    return { id: id.slice(0, 60), title: str(screen['title'], 120) || id.slice(0, 60), note: str(screen['note'], 300),
      blocks: arr(screen['blocks'] ?? screen['children']).map((item, index) => block(item, 0, String(index))).filter((item): item is MaquetteBlock => item !== null) };
  });
  if (!screens.length) return { kind: 'invalid', reason: 'shape', version };
  const ids = new Set(screens.map(screen => screen.id));
  const link = typeof spec['workflow'] === 'string' ? str(spec['workflow'], 200).trim() : '';
  const flow = link ? undefined : parseDiagram(obj(spec['workflow']));
  const diagram = flow?.kind === 'ok' ? flow.diagram : null;
  // A linked diagram is read later: its node ids are not known yet, so a case's path is kept as written.
  const known = (id: string) => link ? true : !!diagram?.nodes.some(node => node.id === id);
  const start = str(spec['start'], 60), device = spec['device'];
  return { kind: 'ok', version, maquette: {
    title: str(spec['title'], 120), start: ids.has(start) ? start : screens[0]!.id, device: device === 'phone' || device === 'desktop' ? device : undefined, screens,
    nav: arr(spec['nav'], 8).map(value => { const item = obj(value); return { label: str(item['label'], 40), goto: str(item['goto'], 60) }; }).filter(item => item.label && ids.has(item.goto)),
    workflow: diagram ? { states: diagram.nodes, transitions: diagram.edges } : null, diagram, diagramLink: isDiagramLink(link) ? link : undefined,
    cases: arr(spec['cases'], 10).map((value): MaquetteCase => {
      const item = obj(value);
      const steps = arr(item['steps'], 20).map(step => { const raw = obj(step); return { screen: str(raw['screen'], 60), caption: str(raw['caption'], 300) }; }).filter(step => ids.has(step.screen));
      return { name: str(item['name'], 80), steps, path: strings(item['path'], 20, 60).filter(known) };
    }).filter(item => item.name && (item.steps.length > 0 || item.path.length > 0)),
  } };
}

/** Every screen id a block tree links to, in order, without repeats. */
export function linksOf(blocks: readonly MaquetteBlock[]): string[] {
  const found = new Set<string>();
  const walk = (list: readonly MaquetteBlock[]) => { for (const item of list) { if (item.goto) found.add(item.goto); walk(item.children); } };
  walk(blocks);
  return [...found];
}

/** A workflow link the viewer follows: a relative `*.diagram.json` path (no scheme, no leading slash, no `..`). */
const isDiagramLink = (link: string): boolean => /\.diagram\.json$/i.test(link) && !/^[a-z][a-z0-9+.-]*:|^\/|(^|\/)\.\.(\/|$)/i.test(link);

/** The path of a linked diagram: `link` resolved against the folder of the maquette at `path`. */
export const diagramPathOf = (path: string, link: string): string => `${path.includes('/') ? path.slice(0, path.lastIndexOf('/') + 1) : ''}${link.replace(/^\.\//, '')}`;

/** True for a path the built-in maquette kind draws: a `.maquette.json` file. */
export const isMaquettePath = (path: string): boolean => /\.maquette\.json$/i.test(path);

/** The screen id a URL fragment names (`#screen=<id>`, alone or among other `&`-separated keys), or undefined. */
export function screenFromFragment(fragment: string | undefined): string | undefined {
  if (!fragment) return undefined;
  try { return new URLSearchParams(fragment.replace(/^#/, '')).get('screen') ?? undefined; } catch { return undefined; }
}

'use client';

// One maquette screen drawn from the host's own shadcn components: each catalogue type is a real Button, Input, NativeSelect, Badge, Table,
// Item, Card or Bubble, so a mock-up looks like the app it announces. A type the catalogue does not know becomes a named placeholder
// (a grey dashed Empty). Blocks with a goto open their screen; the item's CSS gives them a soft ring on hover and focus. Each block sits
// in a box marked `data-feedback-id` (the maquette path, screen id and block id), so a note pinned on it with the feedback item's point mode
// says exactly which block it is about; the screen is a `data-feedback-visible` region, so the block's words go with the note.
import type { ReactNode, Ref } from 'react';
import { BoxIcon } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Bubble, BubbleContent } from '@/components/ui/bubble';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Empty, EmptyContent, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle } from '@/components/ui/empty';
import { Input } from '@/components/ui/input';
import { Item, ItemContent, ItemGroup, ItemTitle } from '@/components/ui/item';
import { Label } from '@/components/ui/label';
import { NativeSelect, NativeSelectOption } from '@/components/ui/native-select';
import { Separator } from '@/components/ui/separator';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import type { Maquette, MaquetteBlock, MaquetteScreen } from './maquette';
import type { MaquetteLabels } from './maquette-labels';

/** Opens a screen by id. */
export type MaquetteGo = (screen: string) => void;
/**
 * How a block reaches other screens: `go` opens one, `hint` names where a goto leads (the button's tooltip). `target` is a block's
 * `data-feedback-id` and `pins` the numbers of the comment pins on it (none while point mode draws its own).
 */
export interface MaquetteLinks {
  readonly go: MaquetteGo;
  readonly hint: (screen: string) => string;
  readonly target: (block: MaquetteBlock) => string;
  readonly pins: (block: MaquetteBlock) => readonly number[];
}

const SKELETON = [92, 100, 64];

function Placeholder({ block, links, labels }: { readonly block: MaquetteBlock; readonly links: MaquetteLinks; readonly labels: MaquetteLabels }) {
  return <div data-testid="maquette-placeholder" data-type={block.type}>
    <Empty data-maquette="placeholder">
      <EmptyHeader>
        <EmptyMedia variant="icon"><BoxIcon aria-hidden="true" /></EmptyMedia>
        <EmptyTitle>{block.label || block.type}</EmptyTitle>
        <EmptyDescription>{block.note || labels.unknownBlock}</EmptyDescription>
      </EmptyHeader>
      {block.goto && <EmptyContent><GotoButton block={block} links={links} label={block.label || block.type} /></EmptyContent>}
    </Empty>
  </div>;
}

// A block with a goto opens its screen (its tooltip names it); one without is drawn but does nothing.
function GotoButton({ block, links, label }: { readonly block: MaquetteBlock; readonly links: MaquetteLinks; readonly label: string }) {
  const target = block.goto;
  return <Button type="button" variant={block.type === 'link' ? 'link' : block.primary ? 'default' : 'outline'} className="w-fit max-w-full pointer-coarse:min-h-11"
    data-testid={target ? 'maquette-goto' : 'maquette-button'} data-goto={target} title={target ? links.hint(target) : undefined} onClick={() => { if (target) links.go(target); }}>
    <span className="truncate">{label || '…'}</span>
  </Button>;
}

/** One block and its children, in its marked box with its comment pins. */
export function MaquetteBlockView({ block, links, labels }: { readonly block: MaquetteBlock; readonly links: MaquetteLinks; readonly labels: MaquetteLabels }): ReactNode {
  const pins = links.pins(block);
  return <div data-testid="maquette-block" data-block={block.id} data-feedback-id={links.target(block)} className="relative min-w-0">
    <BlockBody block={block} links={links} labels={labels} />
    {pins.length > 0 && <Badge data-testid="maquette-pin" data-feedback-ignore="" aria-hidden="true" className="absolute -top-2 -left-2 tabular-nums">{pins.join(' ')}</Badge>}
  </div>;
}

function BlockBody({ block, links, labels }: { readonly block: MaquetteBlock; readonly links: MaquetteLinks; readonly labels: MaquetteLabels }): ReactNode {
  const children = block.children.map((child, index) => <MaquetteBlockView key={index} block={child} links={links} labels={labels} />);
  switch (block.type) {
    case 'heading': return <h4 className="m-0 text-base font-semibold text-balance">{block.label}</h4>;
    case 'text': return <p className="m-0 text-sm text-pretty text-muted-foreground">{block.label}</p>;
    case 'button': case 'link': return <GotoButton block={block} links={links} label={block.label} />;
    case 'input': return <Label className="flex-col items-stretch gap-1.5">{block.label}
      <Input className="pointer-coarse:min-h-11" placeholder={block.placeholder} defaultValue={block.value} /></Label>;
    case 'select': return <Label className="flex-col items-stretch gap-1.5">{block.label}
      <NativeSelect className="w-full pointer-coarse:[&_select]:min-h-11" defaultValue={block.value}>
        {(block.items.length ? block.items : [block.value || block.placeholder || '…']).map((option, index) => <NativeSelectOption key={index} value={option}>{option}</NativeSelectOption>)}
      </NativeSelect></Label>;
    case 'badge': return <Badge variant="secondary">{block.label}</Badge>;
    case 'list': return <ItemGroup className="gap-2">
      {block.label && <p className="m-0 text-sm font-medium">{block.label}</p>}
      {block.items.map((item, index) => <Item key={index} variant="outline" size="sm"><ItemContent><ItemTitle>{item}</ItemTitle></ItemContent></Item>)}
    </ItemGroup>;
    case 'table': return <div className="min-w-0 overflow-x-auto"><Table>
      <TableHeader><TableRow>{block.columns.map((column, index) => <TableHead key={index}>{column}</TableHead>)}</TableRow></TableHeader>
      <TableBody>{block.rows.map((row, index) => <TableRow key={index}>{row.map((cell, column) => <TableCell key={column}>{cell}</TableCell>)}</TableRow>)}</TableBody>
    </Table></div>;
    case 'card': return <Card size="sm">
      {block.label && <CardHeader><CardTitle>{block.label}</CardTitle></CardHeader>}
      {children.length > 0 && <CardContent className="flex flex-col gap-3">{children}</CardContent>}
    </Card>;
    case 'row': return <div className="flex flex-wrap items-start gap-3 *:min-w-40 *:flex-1">{children}</div>;
    case 'stack': return <div className="flex flex-col gap-3">{children}</div>;
    case 'chat': return <Card size="sm">
      {block.label && <CardHeader><CardTitle>{block.label}</CardTitle></CardHeader>}
      <CardContent className="flex flex-col gap-2">
        {block.messages.map((message, index) => <Bubble key={index} align={message.mine ? 'end' : 'start'} variant={message.mine ? 'default' : 'muted'}><BubbleContent>{message.text}</BubbleContent></Bubble>)}
        <Input className="pointer-coarse:min-h-11" placeholder={block.placeholder || '…'} aria-label={block.placeholder || block.label || 'chat'} />
        {children}
      </CardContent>
    </Card>;
    case 'document': return <Card size="sm">
      {block.label && <CardHeader><CardTitle>{block.label}</CardTitle></CardHeader>}
      <CardContent className="flex flex-col gap-2">
        {block.lines.length ? block.lines.map((line, index) => <p key={index} className="m-0 text-sm text-muted-foreground">{line}</p>)
          : SKELETON.map(width => <span key={width} aria-hidden="true" className="block h-2 bg-muted" style={{ width: `${width}%` }} />)}
        {children}
      </CardContent>
    </Card>;
    case 'placeholder': default: return <Placeholder block={block} links={links} labels={labels} />;
  }
}

/** A screen as the app would show it: the app's navigation bar (when the maquette has one), then its blocks. Its name is for screen readers and focus. */
export function MaquetteScreenView({ maquette, screen, links, labels, headingRef }: {
  readonly maquette: Maquette; readonly screen: MaquetteScreen; readonly links: MaquetteLinks; readonly labels: MaquetteLabels;
  readonly headingRef?: Ref<HTMLHeadingElement> | undefined;
}) {
  return <div data-testid="maquette-screen" data-screen={screen.id} data-feedback-visible="" className="flex min-w-0 flex-col gap-4">
    {maquette.nav.length > 0 && <>
      <nav aria-label={labels.appNavigation} className="flex flex-wrap gap-1">
        {maquette.nav.map(item => <Button key={item.goto} type="button" size="sm" variant={item.goto === screen.id ? 'secondary' : 'ghost'} className="pointer-coarse:min-h-11"
          aria-current={item.goto === screen.id ? 'page' : undefined} data-testid="maquette-nav" title={links.hint(item.goto)} onClick={() => links.go(item.goto)}>{item.label}</Button>)}
      </nav>
      <Separator />
    </>}
    <h3 ref={headingRef} tabIndex={-1} data-testid="maquette-screen-title" className="sr-only">{screen.title}</h3>
    {screen.blocks.map((block, index) => <MaquetteBlockView key={index} block={block} links={links} labels={labels} />)}
  </div>;
}

'use client';

// The maquette viewer: a PM agent's `*.maquette.json` mock-up, one screen at a time. The screen is the content; the chrome is one thin bar
// of icons: Back, ‹ 2 / 5 › (also arrow keys and swipe) and a menu holding the guided tours and "How it works" (the workflow, in a dialog).
// During a tour the bar shows the step dots and ×, with the step's caption under it. `maquetteKind` (maquette-kind.ts) is the kind of the pi-app-kinds default
// list for `.maquette.json` files; an app kind placed before it in `artifactKinds` wins. It draws data only: nothing in the file runs.
// The workflow is drawn by the diagram-viewer item's `DiagramView`, inline or from a linked `*.diagram.json`. With `comments` (the feedback
// item's `usePointComments`, structurally) one more icon enters point mode on the screen: a tap on a block pins a note that names the
// maquette path, the screen id and the block id; the pins of the current screen show as small numbers on their blocks.
import { createContext, useContext, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import type { KeyboardEvent, ReactNode, TouchEvent } from 'react';
import { ArrowLeftIcon, ChevronLeftIcon, ChevronRightIcon, CompassIcon, EllipsisIcon, InfoIcon, MessageSquarePlusIcon, TriangleAlertIcon, WorkflowIcon, XIcon } from 'lucide-react';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Toggle } from '@/components/ui/toggle';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { parseDiagram } from '../diagram-viewer/diagram';
import type { Diagram } from '../diagram-viewer/diagram';
import { DiagramView } from '../diagram-viewer/diagram-view';
import { MAQUETTE_FORMAT_VERSION, diagramPathOf, parseMaquette, screenFromFragment } from './maquette';
import type { Maquette, MaquetteBlock, MaquetteCase, MaquetteScreen } from './maquette';
import { maquetteLabelsFor } from './maquette-labels';
import type { MaquetteLabels, MaquetteLocale } from './maquette-labels';
import { MaquetteScreenView } from './maquette-blocks';
import type { MaquetteLinks } from './maquette-blocks';

export { MAQUETTE_FORMAT_VERSION, diagramPathOf, isMaquettePath, linksOf, parseMaquette, screenFromFragment } from './maquette';
export type { Maquette, MaquetteBlock, MaquetteBlockV1, MaquetteCase, MaquetteFileV1, MaquetteParse, MaquetteScreen, MaquetteState, MaquetteTransition, MaquetteWorkflow } from './maquette';
export { defaultMaquetteLabels, frenchMaquetteLabels, maquetteLabelsFor } from './maquette-labels';
export type { MaquetteLabels, MaquetteLocale } from './maquette-labels';

/**
 * Comment pins, structurally the feedback item's `usePointComments(session)`: pass it and the bar shows a comment icon; omit it (no feedback
 * session in the host) and nothing shows.
 */
export interface MaquetteComments {
  /** Point mode is on. */
  readonly active: boolean;
  /** Enters point mode (the person taps blocks to pin notes), or ends it when it is on. */
  readonly point: () => void;
  /** The pins taken: each one's number and the `data-feedback-id` its element sits in. */
  readonly pins: readonly { readonly number: number; readonly target: string }[];
}

/** Reads another file of the workspace as text (the artifact panel passes one): a linked `*.diagram.json`. Undefined when it cannot. */
export type MaquetteRead = (path: string) => Promise<string | undefined>;

/** A block's `data-feedback-id`: `maquette:<path>#screen=<screen id>&block=<block id>`. */
export const maquetteTarget = (path: string | undefined, screen: string, block: string): string => `maquette:${path ?? ''}#screen=${screen}&block=${block}`;

export interface MaquetteViewerProps {
  /** The file's text (JSON). */
  readonly text: string;
  /** The file's path: named by comment pins, and the folder a linked diagram is read from. */
  readonly path?: string | undefined;
  /** Comment pins on blocks (the feedback item's `usePointComments`). */
  readonly comments?: MaquetteComments | undefined;
  /** Reads a linked `*.diagram.json`; without it a linked workflow is not offered. */
  readonly read?: MaquetteRead | undefined;
  /** The page's URL fragment: `screen=<id>` opens that screen (and follows later changes). */
  readonly fragment?: string | undefined;
  /** The base words: English by default. */
  readonly locale?: MaquetteLocale | undefined;
  /** Any word over the locale's. */
  readonly labels?: Partial<MaquetteLabels> | undefined;
  /** A host bar's "…" menu (the pi-app artifact panel's `setMenu`): the tours and "How it works" go there, as with `MaquetteMenuContext`. */
  readonly publishMenu?: ((items: readonly MaquetteMenuEntry[]) => void) | undefined;
}

/** Where the person is: the screens visited (the last is shown) and the guided tour under way. */
interface Walk { readonly history: readonly string[]; readonly tour: { readonly name: string; readonly index: number } | null }

/**
 * A host bar that owns the one "…" menu (the pi-app artifact panel) provides this: the viewer then publishes its tours and "How it works"
 * there instead of drawing a second "…" menu beside the screen counter. Without a provider the viewer keeps its own menu.
 */
export interface MaquetteMenuEntry { readonly id: string; readonly label: string; readonly icon: ReactNode; readonly testId: string; readonly separatorBefore: boolean; readonly onSelect: () => void }
export const MaquetteMenuContext = createContext<((items: readonly MaquetteMenuEntry[]) => void) | undefined>(undefined);

const TYPING = 'input, select, textarea, [contenteditable="true"]';
const ICON = 'pointer-coarse:min-h-11 pointer-coarse:min-w-11';

/** One dot per tour step, the current one in the primary colour. */
function Dots({ count, index, label }: { readonly count: number; readonly index: number; readonly label: string }) {
  return <svg role="img" aria-label={label} data-testid="maquette-dots" width={count * 12} height="8" viewBox={`0 0 ${count * 12} 8`} className="shrink-0">
    {Array.from({ length: count }, (_, i) => <circle key={i} cx={i * 12 + 6} cy="4" r="3" className={i === index ? 'fill-primary' : 'fill-muted-foreground/30'} />)}
  </svg>;
}

/** The diagram of a linked `*.diagram.json`, read when the dialog opens: undefined while reading, null when it cannot be read. */
function useLinked(read: MaquetteRead | undefined, path: string | undefined, open: boolean): Diagram | null | undefined {
  const [loaded, setLoaded] = useState<{ readonly path: string; readonly diagram: Diagram | null }>();
  useEffect(() => {
    if (!open || !path || !read || loaded?.path === path) return undefined;
    let off = false;
    read(path).then(text => text === undefined ? null : parseDiagram(text), () => null).then(parsed => {
      if (!off) setLoaded({ path, diagram: parsed?.kind === 'ok' ? parsed.diagram : null });
    });
    return () => { off = true; };
  }, [open, path, read, loaded?.path]);
  return loaded && loaded.path === path ? loaded.diagram : undefined;
}

/** The workflow diagram, its legend and the cases' `path` highlights, in a dialog opened from the menu. */
function HowItWorks({ maquette, source, labels, open, onOpenChange }: {
  readonly maquette: Maquette; readonly source: DiagramSource; readonly labels: MaquetteLabels; readonly open: boolean; readonly onOpenChange: (open: boolean) => void;
}) {
  const [shown, setShown] = useState<string | null>(null);
  const loaded = useLinked(source.read, source.path, open);
  const diagram = maquette.diagram ?? loaded;
  const highlighted = maquette.cases.filter(item => item.path.length > 0);
  if (!maquette.diagram && !source.path) return null;
  return <Dialog open={open} onOpenChange={onOpenChange}>
    <DialogContent data-testid="maquette-how" className="max-h-[85dvh] overflow-y-auto">
      <DialogHeader><DialogTitle>{labels.howItWorks}</DialogTitle></DialogHeader>
      {diagram ? <DiagramView diagram={diagram} highlight={highlighted.find(item => item.name === shown)?.path ?? diagram.path} labels={labels} />
        : diagram === null ? <Alert variant="destructive" data-testid="maquette-how-error"><TriangleAlertIcon aria-hidden="true" /><AlertTitle>{labels.diagramUnavailable}</AlertTitle></Alert>
          : <p role="status" className="m-0 text-sm text-muted-foreground">{labels.loading}</p>}
      {highlighted.length > 0 && <div role="group" className="flex flex-wrap gap-2">
        {highlighted.map(item => <Button key={item.name} type="button" size="sm" variant={shown === item.name ? 'default' : 'outline'} aria-pressed={shown === item.name}
          data-testid="maquette-case" className="pointer-coarse:min-h-11" onClick={() => setShown(current => current === item.name ? null : item.name)}>{item.name}</Button>)}
      </div>}
    </DialogContent>
  </Dialog>;
}

/** Where a linked diagram is read from: its resolved path and the reader (both absent for an inline workflow, or with no reader). */
interface DiagramSource { readonly path: string | undefined; readonly read: MaquetteRead | undefined }

function Walkthrough({ maquette, labels, fragment, path, comments, read, publishMenu }: {
  readonly maquette: Maquette; readonly labels: MaquetteLabels; readonly fragment: string | undefined;
  readonly path: string | undefined; readonly comments: MaquetteComments | undefined; readonly read: MaquetteRead | undefined;
  readonly publishMenu: ((items: readonly MaquetteMenuEntry[]) => void) | undefined;
}) {
  const exists = (id: string | undefined): id is string => !!id && maquette.screens.some(screen => screen.id === id);
  const linked = screenFromFragment(fragment);
  const [walk, setWalk] = useState<Walk>(() => ({ history: [exists(linked) ? linked : maquette.start], tour: null }));
  const [how, setHow] = useState(false);
  const seen = useRef(new Set<string>());
  const heading = useRef<HTMLHeadingElement>(null);
  const moved = useRef(false);
  const touch = useRef<{ x: number; y: number } | null>(null);
  const screens = maquette.screens;
  const current: MaquetteScreen = screens.find(screen => screen.id === walk.history.at(-1)) ?? screens[0]!;
  const position = screens.indexOf(current);
  const tour: MaquetteCase | undefined = walk.tour ? maquette.cases.find(item => item.name === walk.tour!.name) : undefined;
  const tours = useMemo(() => maquette.cases.filter(item => item.steps.length > 0), [maquette]);
  const titleOf = (id: string) => screens.find(screen => screen.id === id)?.title ?? id;
  // Goto blocks pulse once, the first time their screen is shown.
  // Decided once per shown screen, so a re-render of the same screen (the host menu updating) does not end the pulse.
  const shown = useRef<{ readonly id: string; readonly first: boolean } | undefined>(undefined);
  // eslint-disable-next-line react-hooks/refs -- ref cache of the decision for the shown screen (no setState during render); a re-render of the same screen reuses it
  const view = shown.current?.id === current.id ? shown.current : { id: current.id, first: !seen.current.has(current.id) };
  // eslint-disable-next-line react-hooks/refs -- stores the decision above in the same ref cache
  shown.current = view;
  const firstView = view.first;
  useEffect(() => { seen.current.add(current.id); }, [current.id]);

  const move = (next: Walk) => { moved.current = true; setWalk(next); };
  const go = (id: string) => { if (exists(id) && id !== current.id) move({ history: [...walk.history, id], tour: null }); };
  const step = (delta: number) => {
    if (tour && walk.tour) {
      const index = walk.tour.index + delta, target = tour.steps[index];
      if (target) move({ history: [...walk.history, target.screen], tour: { name: tour.name, index } });
      return;
    }
    const target = screens[position + delta];
    if (target) move({ history: [...walk.history, target.id], tour: null });
  };
  const back = () => { if (walk.history.length > 1) move({ history: walk.history.slice(0, -1), tour: null }); };
  const startTour = (item: MaquetteCase) => move({ history: [...walk.history, item.steps[0]!.screen], tour: { name: item.name, index: 0 } });
  // A later `#screen=<id>` (the PM's "see screen 2" link) opens that screen.
  // eslint-disable-next-line react-hooks/set-state-in-effect -- follows a new fragment link once per change of `linked`; the guard skips the screen already shown
  useEffect(() => { if (exists(linked) && linked !== walk.history.at(-1)) setWalk(previous => ({ history: [...previous.history, linked], tour: null })); }, [linked]); // eslint-disable-line react-hooks/exhaustive-deps -- only a new link moves; the walk and the screen list are read as they are
  // After a move, keyboard focus starts on the new screen, so Tab continues inside the screen just opened.
  useEffect(() => { if (moved.current) { moved.current = false; heading.current?.focus(); } }, [walk]);

  const index = tour && walk.tour ? walk.tour.index : position, count = tour ? tour.steps.length : screens.length;
  const target = (block: MaquetteBlock) => maquetteTarget(path, current.id, block.id);
  // While pointing, the session draws its own numbered pins over the page; the small numbers on the blocks are for afterwards.
  const pins = (block: MaquetteBlock) => comments && !comments.active ? comments.pins.filter(pin => pin.target === target(block)).map(pin => pin.number) : [];
  const links: MaquetteLinks = { go, hint: id => labels.opens(titleOf(id)), target, pins };
  const source: DiagramSource = { path: maquette.diagramLink && read ? diagramPathOf(path ?? '', maquette.diagramLink) : undefined, read };
  const workflow = !!maquette.diagram || !!source.path;
  // Inside a host bar with its own "…" menu, the tours and "How it works" go there (one menu, not two).
  const fromContext = useContext(MaquetteMenuContext);
  const publish = publishMenu ?? fromContext;
  const latestTour = useRef(startTour);
  useLayoutEffect(() => { latestTour.current = startTour; });
  useEffect(() => {
    if (!publish) return undefined;
    const items: MaquetteMenuEntry[] = [
      ...(tour ? [] : tours).map((item, i) => ({ id: `tour-${i}`, label: item.name, icon: <CompassIcon aria-hidden="true" />, testId: 'maquette-tour', separatorBefore: i === 0, onSelect: () => latestTour.current(item) })),
      ...(workflow && !tour ? [{ id: 'how-it-works', label: labels.howItWorks, icon: <WorkflowIcon aria-hidden="true" />, testId: 'maquette-how-open', separatorBefore: true, onSelect: () => setHow(true) }] : []),
    ];
    publish(items);
    return () => publish([]);
  }, [publish, tours, workflow, tour, labels.howItWorks]);
  const onKeyDown = (event: KeyboardEvent) => {
    if (event.defaultPrevented || event.ctrlKey || event.metaKey || event.shiftKey || (event.target as Element).closest?.(TYPING)) return;
    if (event.altKey) { if (event.key === 'ArrowLeft') { event.preventDefault(); back(); } return; }
    if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') { event.preventDefault(); step(event.key === 'ArrowLeft' ? -1 : 1); }
  };
  const onTouchStart = (event: TouchEvent) => { const point = event.touches[0]; touch.current = point ? { x: point.clientX, y: point.clientY } : null; };
  const onTouchEnd = (event: TouchEvent) => {
    const start = touch.current, point = event.changedTouches[0];
    touch.current = null;
    if (!start || !point) return;
    const dx = point.clientX - start.x, dy = point.clientY - start.y;
    if (Math.abs(dx) > 56 && Math.abs(dx) > Math.abs(dy) * 1.5) step(dx < 0 ? 1 : -1);
  };
  const caption = tour && walk.tour ? tour.steps[walk.tour.index]?.caption : undefined;

  return <div data-testid="maquette-walk" data-screen={current.id} data-tour={tour?.name} className="flex min-w-0 flex-col gap-2" onKeyDown={onKeyDown}>
    {/* The viewer's own chrome is never pinned, and keeps working while pointing: walk to another screen and pin there too. */}
    <nav aria-label={labels.screens} data-testid="maquette-stepper" data-feedback-ignore="" className="flex items-center gap-1">
      {walk.history.length > 1 && <Button type="button" variant="ghost" size="icon-sm" className={ICON} aria-label={labels.back} data-testid="maquette-back" onClick={back}><ArrowLeftIcon aria-hidden="true" /></Button>}
      <div className="flex flex-1 items-center justify-center gap-1">
        <Button type="button" variant="ghost" size="icon-sm" className={ICON} aria-label={labels.previous} data-testid="maquette-previous" disabled={index <= 0} onClick={() => step(-1)}><ChevronLeftIcon aria-hidden="true" /></Button>
        {tour ? <Dots count={count} index={index} label={labels.tourStep(index + 1, count)} />
          : <span data-testid="maquette-position" className="min-w-10 text-center text-sm text-muted-foreground tabular-nums">{index + 1} / {count}</span>}
        <Button type="button" variant="ghost" size="icon-sm" className={ICON} aria-label={labels.next} data-testid="maquette-next" disabled={index >= count - 1} onClick={() => step(1)}><ChevronRightIcon aria-hidden="true" /></Button>
      </div>
      {comments && <Tooltip><TooltipTrigger render={<Toggle className={ICON} aria-label={labels.comment} pressed={comments.active}
        data-testid="maquette-comment" onPressedChange={() => comments.point()} />}><MessageSquarePlusIcon aria-hidden="true" /></TooltipTrigger><TooltipContent>{labels.comment}</TooltipContent></Tooltip>}
      {tour ? <Button type="button" variant="ghost" size="icon-sm" className={ICON} aria-label={labels.endTour} data-testid="maquette-end-tour" onClick={() => setWalk(previous => ({ ...previous, tour: null }))}><XIcon aria-hidden="true" /></Button>
        : !publish && (tours.length > 0 || workflow) && <DropdownMenu>
          <DropdownMenuTrigger render={<Button type="button" variant="ghost" size="icon-sm" className={ICON} aria-label={labels.more} data-testid="maquette-menu" />}><EllipsisIcon aria-hidden="true" /></DropdownMenuTrigger>
          <DropdownMenuContent align="end" data-testid="maquette-menu-list">
            {tours.map(item => <DropdownMenuItem key={item.name} className="pointer-coarse:min-h-11" data-testid="maquette-tour" onClick={() => startTour(item)}><CompassIcon aria-hidden="true" />{item.name}</DropdownMenuItem>)}
            {tours.length > 0 && workflow && <DropdownMenuSeparator />}
            {workflow && <DropdownMenuItem className="pointer-coarse:min-h-11" data-testid="maquette-how-open" onClick={() => setHow(true)}><WorkflowIcon aria-hidden="true" />{labels.howItWorks}</DropdownMenuItem>}
          </DropdownMenuContent>
        </DropdownMenu>}
    </nav>
    {caption && <p data-testid="maquette-caption" className="m-0 line-clamp-2 px-1 text-sm text-pretty text-muted-foreground">{caption}</p>}

    <div className={maquette.device === 'phone' ? 'mx-auto flex w-full max-w-sm flex-col gap-2' : 'flex min-w-0 flex-col gap-2'}>
      <div className="min-w-0" data-hint={firstView ? 'pulse' : undefined} onTouchStart={onTouchStart} onTouchEnd={onTouchEnd}>
        <Card data-testid="maquette-frame" data-device={maquette.device ?? 'panel'}><CardContent>
          <MaquetteScreenView key={current.id} maquette={maquette} screen={current} links={links} labels={labels} headingRef={heading} />
        </CardContent></Card>
      </div>
      {current.note && <div className="flex min-w-0 items-center gap-1 px-1">
        <p data-testid="maquette-note" title={current.note} className="m-0 min-w-0 flex-1 truncate text-xs text-muted-foreground">{current.note}</p>
        <Popover>
          <PopoverTrigger render={<Button type="button" variant="ghost" size="icon-xs" className={ICON} aria-label={labels.aboutScreen} data-testid="maquette-note-more" />}><InfoIcon aria-hidden="true" /></PopoverTrigger>
          <PopoverContent align="end" data-testid="maquette-note-full">{current.note}</PopoverContent>
        </Popover>
      </div>}
    </div>
    <p aria-live="polite" className="m-0 sr-only">{labels.showing(current.title)}</p>
    <HowItWorks maquette={maquette} source={source} labels={labels} open={how} onOpenChange={setHow} />
  </div>;
}

/** A maquette file drawn one screen at a time; a newer format version shows a notice, an unreadable file an inline error. */
export function MaquetteViewer({ text, fragment, locale, labels: given, path, comments, read, publishMenu }: MaquetteViewerProps) {
  const labels = useMemo(() => maquetteLabelsFor(locale, given), [locale, given]);
  const parsed = useMemo(() => parseMaquette(text), [text]);
  const newer = parsed.version !== undefined && parsed.version > MAQUETTE_FORMAT_VERSION;
  const notice = newer && <Alert data-testid="maquette-newer"><InfoIcon aria-hidden="true" /><AlertTitle>{labels.newerTitle}</AlertTitle><AlertDescription>{labels.newer(parsed.version!)}</AlertDescription></Alert>;
  return <section data-boring="maquette-viewer" data-state={parsed.kind} aria-label={parsed.kind === 'ok' ? parsed.maquette.title || labels.kind : labels.kind}
    className="mx-auto flex w-full max-w-5xl min-w-0 flex-col gap-2 px-3 pt-1 pb-4 sm:px-6">
    {notice}
    {parsed.kind === 'ok' ? <Walkthrough maquette={parsed.maquette} labels={labels} fragment={fragment} path={path} comments={comments} read={read} publishMenu={publishMenu} />
      : <Alert variant="destructive" data-testid="maquette-error" data-reason={parsed.reason}><TriangleAlertIcon aria-hidden="true" /><AlertTitle>{labels.errorTitle}</AlertTitle>
        <AlertDescription>{parsed.reason === 'json' ? labels.invalidJson : labels.invalidShape}</AlertDescription></Alert>}
  </section>;
}

'use client';

import { lazy } from 'react';
import type { ComponentType, ReactNode } from 'react';
import { LayoutTemplateIcon } from 'lucide-react';
import { isMaquettePath } from './maquette';
import { maquetteLabelsFor } from './maquette-labels';
import type { MaquetteLabels, MaquetteLocale } from './maquette-labels';
import type { MaquetteComments, MaquetteMenuEntry, MaquetteRead } from './maquette-viewer';

// The viewer loads only when a maquette opens: this module (match, label, icon) is all a host's first paint carries.
const MaquetteViewer = lazy(() => import('./maquette-viewer').then(module => ({ default: module.MaquetteViewer })));

/**
 * The artifact kind of a maquette file (structurally an `ArtifactKind` of pi-artifacts): it matches `*.maquette.json`, names it, gives its icon
 * and draws it with `MaquetteViewer`, loaded on first open. It is in the pi-app-kinds default list (`defaultKinds`); kinds in `artifactKinds` are consulted in order.
 */
export interface MaquetteKind {
  readonly match: (target: { readonly resource: { readonly path: string } }) => boolean;
  readonly label: string;
  readonly icon: ComponentType<{ readonly className?: string; readonly 'aria-hidden'?: boolean | 'true' }>;
  readonly renderer: (props: {
    readonly text: string; readonly fragment?: string | undefined;
    readonly artifact?: { readonly target: { readonly resource: { readonly path: string } } } | undefined; readonly read?: MaquetteRead | undefined;
    readonly setMenu?: ((items: readonly MaquetteMenuEntry[]) => void) | undefined;
  }) => ReactNode;
}

/**
 * A maquette kind in `locale` ("Mock-up" in English, "Maquette" in French) with any word overridden. `comments` (the feedback item's
 * `usePointComments(session)`) adds the comment icon; pass a fresh kind when it changes.
 */
export function createMaquetteKind({ locale, labels, comments }: {
  readonly locale?: MaquetteLocale | undefined; readonly labels?: Partial<MaquetteLabels> | undefined; readonly comments?: MaquetteComments | undefined;
} = {}): MaquetteKind {
  return {
    match: target => isMaquettePath(target.resource.path),
    label: maquetteLabelsFor(locale, labels).kind,
    icon: LayoutTemplateIcon,
    renderer: ({ text, fragment, artifact, read, setMenu }) => <MaquetteViewer text={text} fragment={fragment} locale={locale} labels={labels}
      path={artifact?.target.resource.path} comments={comments} read={read} publishMenu={setMenu} />,
  };
}

/** The built-in maquette kind, in English. */
export const maquetteKind: MaquetteKind = createMaquetteKind();
